const cors = (request, env) => {
  const origin = request.headers.get("Origin") || "";
  const allowed = String(env.ALLOWED_ORIGINS || "https://messageweb.xyz,https://www.messageweb.xyz")
    .split(",").map(s => s.trim()).filter(Boolean);
  const allow = origin && allowed.includes(origin)
    ? origin
    : (!origin ? (allowed[0] || "https://messageweb.xyz") : "");

  return {
    ...(allow ? { "Access-Control-Allow-Origin": allow } : {}),
    "Access-Control-Allow-Methods": "GET,POST,PUT,PATCH,DELETE,OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type,Authorization",
    "Access-Control-Max-Age": "86400",
    "Vary": "Origin",
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "strict-origin-when-cross-origin"
  };
};

const json = (data, status = 200, headers = {}) =>
  new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      ...headers
    }
  });

const enc = s => new TextEncoder().encode(s);

// 别写 String.fromCharCode(...arr)，字节一多就爆栈，老实循环
const b64u = bytes => {
  const arr = new Uint8Array(bytes);
  let binary = "";
  for (let i = 0; i < arr.length; i++) {
    binary += String.fromCharCode(arr[i]);
  }
  return btoa(binary)
    .replace(/=/g, "")
    .replace(/\+/g, "-")
    .replace(/\//g, "_");
};

const unb64u = s =>
  Uint8Array.from(
    atob(s.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((s.length + 3) % 4)),
    c => c.charCodeAt(0)
  );

// 定长比较，别让比对耗时泄露哈希前缀
function timingSafeEqualStr(a, b) {
  const strA = String(a || "");
  const strB = String(b || "");
  if (strA.length !== strB.length) return false;
  let diff = 0;
  for (let i = 0; i < strA.length; i++) {
    diff |= strA.charCodeAt(i) ^ strB.charCodeAt(i);
  }
  return diff === 0;
}

async function hashPassword(password, saltHex) {
  const salt = saltHex
    ? Uint8Array.from((saltHex.match(/.{2}/g) || []).map(x => parseInt(x, 16)))
    : crypto.getRandomValues(new Uint8Array(16));

  const key = await crypto.subtle.importKey("raw", enc(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", salt, iterations: 100000, hash: "SHA-256" },
    key,
    256
  );

  return {
    salt: [...salt].map(x => x.toString(16).padStart(2, "0")).join(""),
    hash: b64u(bits)
  };
}

async function verifyPassword(password, salt, expected) {
  if (!salt || !expected) return false;
  const v = await hashPassword(password, salt);
  return timingSafeEqualStr(v.hash, expected);
}

async function jwtSign(payload, secret) {
  const header = b64u(enc(JSON.stringify({ alg: "HS256", typ: "JWT" })));
  const body = b64u(enc(JSON.stringify(payload)));
  const msg = header + "." + body;
  const key = await crypto.subtle.importKey(
    "raw",
    enc(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  return msg + "." + b64u(await crypto.subtle.sign("HMAC", key, enc(msg)));
}

async function jwtVerify(token, secret) {
  try {
    const p = token.split(".");
    if (p.length !== 3) return null;

    const key = await crypto.subtle.importKey(
      "raw",
      enc(secret),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["verify"]
    );

    const ok = await crypto.subtle.verify(
      "HMAC",
      key,
      unb64u(p[2]),
      enc(p[0] + "." + p[1])
    );
    if (!ok) return null;

    const data = JSON.parse(new TextDecoder().decode(unb64u(p[1])));
    if (typeof data.exp !== "number" || data.exp < Date.now() / 1000) return null;
    return data;
  } catch {
    return null;
  }
}

function err(message, status = 400) {
  return Object.assign(new Error(message), { status });
}

async function body(req) {
  try {
    return await req.json();
  } catch {
    throw err("请求内容不是有效 JSON", 400);
  }
}

function secret(env, name, fallback) {
  const value = env[name];
  if (typeof value === "string" && value.trim()) return value.trim();
  return fallback;
}

async function getUser(request, env) {
  const h = request.headers.get("Authorization") || "";
  const token = h.startsWith("Bearer ") ? h.slice(7).trim() : "";
  if (!token) throw err("请先登录", 401);

  const jwtSecret = secret(env, "JWT_SECRET", "");
  if (!jwtSecret) throw err("服务器尚未配置 JWT_SECRET", 500);

  const claims = await jwtVerify(token, jwtSecret);
  if (!claims) throw err("登录已失效，请重新登录", 401);

  const u = await env.DB.prepare(
    "SELECT id,username,display_name,role,created_at FROM users WHERE id=?"
  ).bind(claims.sub).first();

  if (!u) throw err("账号不存在", 401);
  return u;
}

function needAdmin(u) {
  if (u.role !== "admin") throw err("仅管理员可以执行此操作", 403);
}

async function ensureAdmin(env) {
  const username = env.ADMIN_USERNAME || "admin";
  const password = env.ADMIN_PASSWORD;
  if (!password) return null;

  let u = await env.DB.prepare("SELECT id FROM users WHERE username=?").bind(username).first();

  if (!u) {
    const p = await hashPassword(password);
    await env.DB.prepare(
      "INSERT INTO users(username,display_name,password_salt,password_hash,role,created_at) VALUES(?,?,?,?,?,?)"
    ).bind(
      username,
      env.ADMIN_DISPLAY_NAME || "系统管理员",
      p.salt,
      p.hash,
      "admin",
      new Date().toISOString()
    ).run();

    u = await env.DB.prepare("SELECT id FROM users WHERE username=?").bind(username).first();
  }

  return u;
}

let lastSeedAt = 0;
let schemaInitialized = false;

async function ensureSchema(env) {
  if (schemaInitialized) return;
  try {
    await env.DB.batch([
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL UNIQUE,
        display_name TEXT NOT NULL,
        password_salt TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'student',
        created_at TEXT NOT NULL
      )`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS notices (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        category TEXT NOT NULL DEFAULT '校园通知',
        audience TEXT NOT NULL DEFAULT '全体学生',
        body TEXT NOT NULL,
        deadline TEXT DEFAULT '',
        publisher_id INTEGER NOT NULL,
        created_at TEXT NOT NULL
      )`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS tasks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        notice_id INTEGER,
        title TEXT NOT NULL,
        due_date TEXT DEFAULT '',
        status TEXT NOT NULL DEFAULT 'pending',
        created_at TEXT NOT NULL
      )`),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_tasks_user_id ON tasks(user_id)`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS user_schedules (
        user_id INTEGER PRIMARY KEY,
        start_date TEXT NOT NULL DEFAULT '2026-08-31',
        total_weeks INTEGER NOT NULL DEFAULT 18,
        courses_json TEXT NOT NULL DEFAULT '[]',
        updated_at TEXT NOT NULL
      )`),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_tasks_notice_id ON tasks(notice_id)`),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_notices_created_at ON notices(created_at DESC)`)
    ]);
    schemaInitialized = true;
  } catch (error) {
    console.error("[schema] D1 schema initialization failed", error);
    throw error;
  }
}

async function seed(env) {
  // 每分钟最多跑一次，不然每个请求都要查一遍库
  const nowMs = Date.now();
  if (nowMs - lastSeedAt < 60000) return;
  lastSeedAt = nowMs;

  await ensureSchema(env);
  await ensureAdmin(env);

  const count = await env.DB.prepare("SELECT COUNT(*) AS n FROM notices").first();
  if (count?.n === 0) {
    const a = await env.DB.prepare(
      "SELECT id FROM users WHERE role='admin' ORDER BY id LIMIT 1"
    ).first();

    if (a) {
      const now = new Date().toISOString();
      const demoNotices = [
        [
          "新学期校园事务办理提醒（演示）",
          "办事提醒",
          "全体学生",
          "此为演示公告。正式使用时请替换为已公开或获授权的正式通知。具体要求以学校正式通知为准。",
          ""
        ],
        [
          "学生意见与建议征集（演示）",
          "学生工作",
          "全体学生",
          "欢迎通过学院指定渠道提交意见建议。此内容为演示数据，不代表学校正式安排。",
          ""
        ]
      ];
      await env.DB.batch(
        demoNotices.map(n =>
          env.DB.prepare(
            "INSERT INTO notices(title,category,audience,body,deadline,publisher_id,created_at) VALUES(?,?,?,?,?,?,?)"
          ).bind(...n, a.id, now)
        )
      );
    }
  }

  if (env.DEMO_SEED === "0") return;

  const demoUsername = env.DEMO_USERNAME || "demo_student";
  let du = await env.DB.prepare("SELECT id FROM users WHERE username=?").bind(demoUsername).first();
  if (!du) {
    const p = await hashPassword(env.DEMO_PASSWORD || "demo123456");
    const r = await env.DB.prepare(
      "INSERT INTO users(username,display_name,password_salt,password_hash,role,created_at) VALUES(?,?,?,?,?,?)"
    ).bind(
      demoUsername,
      "演示同学",
      p.salt,
      p.hash,
      "student",
      new Date().toISOString()
    ).run();
    du = { id: r.meta.last_row_id };
  }

  if (du) {
    const has = await env.DB.prepare("SELECT COUNT(*) AS n FROM tasks WHERE user_id=?").bind(du.id).first();
    if (!has?.n) {
      const firstNotice = await env.DB.prepare("SELECT id FROM notices ORDER BY id LIMIT 1").first();
      if (firstNotice) {
        const now = new Date().toISOString();
        const demoTasks = [
          ["重修报名：确认上学期不及格课程", "2026-09-11", "completed"],
          ["四六级考试报名与缴费确认", "2026-10-25", "pending"],
          ["奖学金申请审批表提交", "2026-10-15", "pending"],
          ["图书馆逾期图书归还", "2026-10-18", "completed"]
        ];
        await env.DB.batch(
          demoTasks.map(([title, due, status]) =>
            env.DB.prepare(
              "INSERT INTO tasks(user_id,notice_id,title,due_date,status,created_at) VALUES(?,?,?,?,?,?)"
            ).bind(du.id, firstNotice.id, title, due, status, now)
          )
        );
      }
    }
  }
}

const publicUser = u => ({
  id: u.id,
  username: u.username,
  display_name: u.display_name,
  role: u.role,
  created_at: u.created_at
});

