毕业生主流职业发展需求与培养目标吻合度
通过对毕业5年左右的毕业生进行问卷跟踪调查，或组织返校校友座谈会，及时了解毕业生对工作岗位的适应状况、了解毕业生的职业发展对学校教育的需求，评价校友的主流职业发展需求及与本专业人才培养目标的吻合度。
