两年
用人单位对人才的需求与培养目标吻合度
通过问卷调查或走访调研等形式，了解行业发展趋势和用人单位对专业人才的需求，以及毕业生岗位胜任能力，评价用人单位的需求与培养目标的吻合度。同时获取用人单位对专业办学定位、培养目标、课程设置、毕业生综合能力培养等方面的意见和建议，为持续改进提供依据。
