function knowledgeTerms(question) {
  const q = String(question || "").toLowerCase().trim().slice(0, 180);
  const terms = [];
  const seen = new Set();
  const add = term => {
    if (term.length >= 2 && !STOP_TERMS.has(term) && !seen.has(term)) {
      seen.add(term);
      terms.push(term);
    }
  };
  const words = q.match(/[a-z0-9_./-]+|[\u3400-\u9fff]+/g) || [];
  for (const word of words) {
    if (/^[\u3400-\u9fff]+$/.test(word)) {
      add(word);
      for (let n = Math.min(5, word.length); n >= 2; n--) {
        for (let i = 0; i + n <= word.length; i++) add(word.slice(i, i + n));
      }
    } else if (word.length > 1) {
      add(word);
    }
    if (terms.length >= 40) break;
  }
  for (const [spoken, expansions] of QUERY_SYNONYMS) {
    if (!q.includes(spoken)) continue;
    for (const term of expansions) add(term);
  }
  return terms.slice(0, 56);
}

const RETRIEVAL_CACHE = new Map();
const RETRIEVAL_CACHE_MAX = 240;

function retrieveKnowledge(question) {
  const key = String(question || "").toLowerCase().replace(/\s+/g, " ").trim().slice(0, 180);
  const cached = RETRIEVAL_CACHE.get(key);
  if (cached) return cached;
  const result = retrieveKnowledgeCore(key);
  if (RETRIEVAL_CACHE.size >= RETRIEVAL_CACHE_MAX) RETRIEVAL_CACHE.clear();
  RETRIEVAL_CACHE.set(key, result);
  return result;
}

const INTENT_DOC_HINTS = [
  { re: /缓考|缓补考|补考|重修|考试资格|缺课|旷课|考场|作弊|违纪|期末考试|期末成绩|挂科/, docs: ["考试管理规定", "考试违纪、作弊处理"] },
  { re: /论文|查重|AIGC|人工智能|答辩|开题|选题|盲审|毕业设计/, docs: ["毕业论文"] },
  { re: /人工智能|AIGC|\bAI\b|大模型|CHATGPT/i, docs: ["人工智能工具"] },
  { re: /学位|绩点/, docs: ["学士学位"] },
  { re: /公寓|宿舍|寝室|留宿|住宿|门禁/, docs: ["学生公寓", "公寓"] },
  { re: /心理|咨询|抑郁|焦虑|危机|情绪/, docs: ["心理咨询", "心理健康", "心理危机"] },
  { re: /奖学金|助学金|困难|资助|勤工助学|助学贷款|建档立卡/, docs: ["奖", "助学金", "困难", "资助", "勤工助学", "贷款"] },
  { re: /转专业|专业分流|换专业|分流/, docs: ["转专业"] },
  { re: /休学|复学|退学|保留学籍|延期毕业|留级|学籍异动/, docs: ["学籍", "休学", "退学", "留级", "参军入伍"] },
  { re: /学分置换|学分认定|成绩认定|置换/, docs: ["学分置换", "学分认定"] },
  { re: /综合素质|评优|三好学生|测评/, docs: ["综合素质", "评优"] },
  { re: /处分|记过|警告|留校察看|开除学籍|记入档案/, docs: ["处分办理流程"] },
  { re: /毕业证|学位证|证书补办|证书丢|丢失|补办/, docs: ["证书补办"] },
  { re: /实习|实践教学|教育实习|见习/, docs: ["实习"] },
  { re: /实验|实训|实验室/, docs: ["实验教学"] },
  { re: /教材/, docs: ["教材"] },
  { re: /评教|教学评价|学生评教/, docs: ["评教"] },
  { re: /教学事故/, docs: ["教学事故"] },
  { re: /信息员/, docs: ["信息员"] },
  { re: /学科竞赛|竞赛/, docs: ["学科竞赛"] },
  { re: /创新创业|大创|孵化基地/, docs: ["创新创业"] },
  { re: /辅导员/, docs: ["辅导员"] },
  { re: /调课|停课|代课|补课/, docs: ["调课、停课"] }
];

const GENERIC_TITLE_TERMS = new Set(["学生", "学校", "学院", "办理", "流程", "申请", "材料", "规定", "办法", "管理", "工作", "实施", "细则", "指导", "意见", "通知"]);

/* ---- 检索层 ---- */
const BM25_K1 = 1.25;
const BM25_B = 0.72;
const TITLE_WEIGHT = 2.5;
const MAX_TERMS = 24;

const KB_STOP_TERMS = new Set(
  [...STOP_TERMS].filter(t => !["咨询", "办理", "申请", "事项", "了解", "想要", "现在"].includes(t))
);
for (const t of ["满足", "符合", "达到", "具备", "相关", "有关", "进行", "按照", "根据", "通过"]) KB_STOP_TERMS.add(t);

const KB_LEN = new Float64Array(SEARCHABLE_CHUNKS.length);
let KB_LEN_SUM = 0;
SEARCHABLE_CHUNKS.forEach((c, i) => {
  c.idx = i;
  const len = c.hay.length + TITLE_WEIGHT * c.titleHay.length;
  KB_LEN[i] = len;
  KB_LEN_SUM += len;
});
const AVG_LEN = Math.max(1, KB_LEN_SUM / Math.max(1, SEARCHABLE_CHUNKS.length));

const TITLE_SKIP = new Set([
  "补办", "预约", "证明", "报名", "登记", "审核", "评定", "认定", "发放", "查询",
  "申请", "办理", "流程", "指南", "手续", "材料", "规定", "办法", "管理"
]);

const ALL_TITLES = SEARCHABLE_CHUNKS.map(c => c.titleHay).join("\n");

const DOC_SEQ = new Map();
for (const c of SEARCHABLE_CHUNKS) {
  const key = c.docTitle || c.name;
  if (!DOC_SEQ.has(key)) DOC_SEQ.set(key, []);
  DOC_SEQ.get(key).push(c);
}

const dfCache = new Map();
function kbDf(term) {
  const hit = dfCache.get(term);
  if (hit !== undefined) return hit;
  let df = 0;
  for (const c of SEARCHABLE_CHUNKS) if (c.hay.includes(term)) df++;
  if (dfCache.size >= 8000) dfCache.clear();
  dfCache.set(term, df);
  return df;
}

const QUESTION_RE = /(什么时候|什么时间|多少天|多少周|多少分|多少钱|多少个|多长时间|多久|何时|哪一天|哪天|几号|几点|是多少|有哪些|怎么办|怎么做|怎么弄|怎么样|怎么|如何|为什么|什么样|需要准备|需要|要不要|能不能|可不可以|可以吗|是不是)/g;
const FILLER_RE = /[的了是我你们请问哪什么多少能有没想该那个会都也还就与和或及在到去来吧呢啊呀吗嘛哦嗯把被让给对从向于其之啦哈]/g;

const EDGE_STOP = /[的了着过很更最太都也还就才只又再却并而但或者如若虽因由从向对把被让给于其之所有和与及等以为在到去来可要需该能会想请吗呢吧啊呀哦嗯哈不无未非必]/;
const edgeReject = (term) => EDGE_STOP.test(term[0]) || EDGE_STOP.test(term[term.length - 1]);

function kbTopicWords(question) {
  return String(question || "")
    .toLowerCase()
    .replace(QUESTION_RE, " ")
    .replace(FILLER_RE, " ")
    .split(/[^\u3400-\u9fffa-z0-9]+/)
    .map(s => s.trim())
    .filter(s => s.length >= 2 && s.length <= 10);
}

function kbQueryTerms(question) {
  const q = String(question || "").toLowerCase().slice(0, 200);
  const runs = q.match(/[a-z0-9_./-]+|[\u3400-\u9fff]+/g) || [];
  const cand = [];
  for (const run of runs) {
    if (!/^[\u3400-\u9fff]/.test(run)) {
      if (run.length > 1) cand.push(run);
      continue;
    }
    for (let n = Math.min(4, run.length); n >= 2; n--) {
      for (let i = 0; i + n <= run.length; i++) cand.push(run.slice(i, i + n));
    }
  }
  const N = SEARCHABLE_CHUNKS.length;
  const uniq = [...new Set(cand)].sort((a, b) => b.length - a.length || (a < b ? -1 : 1));
  const valid = [];
  for (const t of uniq) {
    if (KB_STOP_TERMS.has(t) || GENERIC_TITLE_TERMS.has(t)) continue;
    if (edgeReject(t)) continue;
    const df = kbDf(t);
    if (!df) continue;
    if (df > N * 0.5) continue;                 
    if (t.length === 2 && df < 2) continue;      
    valid.push({ t, df });
  }
  const validSorted = [...valid].sort((a, b) => b.t.length - a.t.length);
  const surviving = [];
  for (const item of validSorted) {
    if (surviving.some(k => k.t.length > item.t.length && k.t.includes(item.t))) continue;
    surviving.push(item);
  }
  const scored = surviving.map(item => ({
    ...item,
    v: Math.log(1 + (N - item.df + 0.5) / (item.df + 0.5)) * Math.min(item.t.length, 4)
  })).sort((a, b) => b.v - a.v);
  const kept = scored.slice(0, MAX_TERMS);
  const terms = kept.map(x => ({ t: x.t, w: 1, v: x.v }));
  const has = t => terms.some(x => x.t === t);
  for (const w of kbTopicWords(q)) {
    const phrase = w.slice(0, 8);
    if (phrase.length >= 3 && !has(phrase) && kbDf(phrase) > 0) {
      terms.push({ t: phrase, w: 1.8, v: 9 });
    }
  }
  for (const [spoken, expansions] of QUERY_SYNONYMS) {
    if (!q.includes(spoken)) continue;
    for (const term of expansions) {
      if (term.length >= 2 && !has(term) && kbDf(term) > 0) terms.push({ t: term, w: 0.85, v: 4 });
    }
  }
  return terms.slice(0, MAX_TERMS + 6);
}

function retrieveKnowledgeCore(question) {
  const q = String(question || "").toLowerCase().replace(/\s+/g, " ").trim().slice(0, 200);
  if (!q) return [];
  const terms = kbQueryTerms(q);
  if (!terms.length) return [];

  const N = SEARCHABLE_CHUNKS.length;
  const T = terms.length;
  const tfBody = new Uint8Array(T * N);
  const tfTitle = new Uint8Array(T * N);
  for (let i = 0; i < N; i++) {
    const c = SEARCHABLE_CHUNKS[i];
    for (let j = 0; j < T; j++) {
      const term = terms[j].t;
      let pos = c.hay.indexOf(term);
      if (pos < 0) continue;
      let count = 1;
      let next = pos + term.length;
      while (count < 4 && (next = c.hay.indexOf(term, next)) !== -1) { count++; next += term.length; }
      tfBody[j * N + i] = count;
      if (c.titleHay.includes(term)) tfTitle[j * N + i] = 1;
    }
  }

  const idf = new Float32Array(T);
  for (let j = 0; j < T; j++) {
    let df = 0;
    for (let i = 0; i < N; i++) if (tfBody[j * N + i]) df++;
    idf[j] = Math.max(0.12, Math.log(1 + (N - df + 0.5) / (df + 0.5)));
  }

  const keyTerms = [...terms]
    .map((x, i) => ({ ...x, i }))
    .sort((a, b) => (b.v || 0) - (a.v || 0))
    .slice(0, 6);
  const keyIndex = new Set(keyTerms.map(x => x.i));
  let keyTotal = 0;
  for (const x of keyTerms) keyTotal += x.w;

  const scored = [];
  for (let i = 0; i < N; i++) {
    const c = SEARCHABLE_CHUNKS[i];
    const dl = KB_LEN[i];
    let score = 0;
    let matched = 0;
    let keyMatched = 0;
    let phraseHit = 0;
    for (let j = 0; j < T; j++) {
      const tb = tfBody[j * N + i];
      if (!tb) continue;
      const w = terms[j].w;
      matched++;
      if (keyIndex.has(j)) keyMatched += w;
      if (w >= 1.5) phraseHit++;
      const tf = tb + TITLE_WEIGHT * tfTitle[j * N + i];
      const norm = (tf * (BM25_K1 + 1)) / (tf + BM25_K1 * (1 - BM25_B + BM25_B * (dl / AVG_LEN)));
      score += w * idf[j] * norm;
    }
    if (!score) continue;
    if (phraseHit) score *= 1 + Math.min(0.4, 0.2 * phraseHit);
    score *= c.category === "办事指南" ? Math.max(0.86, 0.55 + c.quality * 0.45) : 0.55 + c.quality * 0.45;
    const coverage = keyTotal ? keyMatched / Math.max(keyTotal, 1.2) : 0;
    const fullCoverage = matched / Math.max(1, T);
    const scoreRel = score / (score + 5.5);
    scored.push({
      name: c.name,
      docTitle: c.docTitle,
      dept: c.dept,
      category: c.category,
      date: c.date,
      url: c.url,
      content: c.content,
      quality: c.quality,
      idx: i,
      score,
      hits: matched,
      termCount: T,
      coverage,
      fullCoverage,
      rel: Math.min(1, coverage * 0.66 + scoreRel * 0.34)
    });
  }
  if (!scored.length) return [];

  
  const topValueTerms = [...terms].sort((a, b) => (b.v || 0) - (a.v || 0)).slice(0, 5).map(x => x.t);

  const docMap = new Map();
  for (const s of scored) {
    const key = s.docTitle || s.name;
    let d = docMap.get(key);
    if (!d) { d = { docTitle: key, best: s, chunks: 0 }; docMap.set(key, d); }
    d.chunks++;
    if (s.score > d.best.score) d.best = s;
  }

  const intentDocs = INTENT_DOC_HINTS.filter(h => h.re.test(q)).flatMap(h => h.docs);
  const procedureIntent = /怎么办|怎么|如何|流程|办理|申请|材料|手续|需要准备|准备哪些|步骤|到哪|找谁/.test(q);
  const standardIntent = /标准|要求|规定|条件|资格|多少|比例|上限|不得|禁止|限制/.test(q);

  const titleTerms = [...new Set([
    ...[...terms].sort((a, b) => (b.v || 0) - (a.v || 0)).slice(0, 4).map(x => x.t),
    ...[...terms].sort((a, b) => kbDf(b.t) - kbDf(a.t)).slice(0, 3).map(x => x.t)
  ])].filter(t => t.length >= 2);

  for (const d of docMap.values()) {
    const title = d.docTitle || "";
    d.score = d.best.score * (1 + Math.min(0.2, 0.05 * (d.chunks - 1)));
    d.rel = Math.min(1, d.best.rel * (1 + Math.min(0.1, 0.025 * (d.chunks - 1))));
    if (intentDocs.length && intentDocs.some(t => title.includes(t))) {
      d.score *= 1.35;
      d.rel = Math.min(1, d.rel * 1.12 + 0.05);
    }
    if (procedureIntent && /办事指南|办理流程|流程|指南|补办/.test(title)) {
      d.score *= 1.5;
      d.rel = Math.min(1, d.rel * 1.15 + 0.05);
    }
    if (procedureIntent && /评价指标|指标体系|评价办法|评估标准|质量评价|工作量测算|听课制度|工作规范|评价体系/.test(title)) {
      d.score *= 0.6;
      d.rel *= 0.86;
    }
    if (standardIntent && /指标体系|评价标准|评估标准|质量标准/.test(title)) {
      d.score *= 1.12;
      d.rel = Math.min(1, d.rel * 1.06);
    }
    const relRaw = d.rel;   
    let titleHit = 0;
    for (const t of titleTerms) {
      if (t.length < 2) continue;
      if (title.includes(t)) { titleHit++; continue; }
      if (t.length < 3) continue;
      const slices = [];
      for (let i = 0; i + 2 <= t.length; i++) slices.push(t.slice(i, i + 2));
      const need = t.length >= 4 ? 2 : slices.length;
      let got = 0;
      for (const g of slices) if (title.includes(g)) got++;
      if (got >= need) titleHit++;
    }
    if (titleHit) {
      d.score *= 1 + Math.min(0.45, 0.2 * titleHit);
      d.rel = Math.min(1, d.rel * (1 + Math.min(0.2, 0.08 * titleHit)));
    } else {
      d.score *= 0.78;
      d.rel = Math.min(d.rel * 0.9, 0.55);
    }
    d.tier = titleHit ? 1 : 0;
    d.relRaw = relRaw;
  }

  if (![...docMap.values()].some(d => d.tier)) {
    for (const d of docMap.values()) d.rel = d.relRaw;
  }

  const rankedDocs = [...docMap.values()].sort((a, b) => (b.tier - a.tier) || (b.score - a.score));
  const byIdx = new Map(scored.map(s => [s.idx, s]));

  const selected = [];
  const seen = new Set();
  let total = 0;
  const push = item => {
    if (seen.has(item.idx)) return false;
    if (total + item.content.length > 10500 && selected.length) return false;
    seen.add(item.idx);
    selected.push(item);
    total += item.content.length;
    return true;
  };

  const primaries = [];
  for (const d of rankedDocs) {
    if (primaries.length >= 4) break;
    if (d.rel < 0.16) break;
    if (push(d.best)) {
      d.best.rel = d.rel;
      primaries.push(d);
    }
  }
  for (const d of primaries) {
    if (selected.length >= 5) break;
    const siblings = DOC_SEQ.get(d.docTitle) || [];
    const at = siblings.findIndex(c => c.idx === d.best.idx);
    if (at < 0) continue;
    for (const step of [-1, 1]) {
      if (selected.length >= 5) break;
      const c = siblings[at + step];
      if (!c) continue;
      const s = byIdx.get(c.idx);
      if (!s) continue;
      if (s.score < d.best.score * 0.5) continue;
      s.rel = d.rel;
      push(s);
    }
  }

  selected.titleEvidence = topValueTerms.some(t => {
    if (t.length < 2 || TITLE_SKIP.has(t)) return false;
    if (ALL_TITLES.includes(t)) return true;
    for (let i = 0; i + 2 <= t.length; i++) {
      if (ALL_TITLES.includes(t.slice(i, i + 2))) return true;
    }
    return false;
  });
  return selected;
}

function isSpecificSourceUrl(value) {
  const raw = String(value || "").trim();
  if (!raw) return false;
  try {
    const u = new URL(raw);
    if (u.protocol !== "https:" && u.protocol !== "http:") return false;
    if (!u.hostname || !u.hostname.includes(".")) return false;
    const path = u.pathname.replace(/\/+$/, "").toLowerCase();
    if (["", "/", "/index.htm", "/index.html", "/index.jsp", "/index.php", "/tzgg.htm", "/tzgg.html", "/通知公告"].includes(path)) return false;
    if (/\/(list|index|more|search|tag|category|channel|column)[_-]?\d*\.(htm|html|php|jsp|aspx)$/i.test(path)) return false;
    if (/[?&](page|pageno|p)=\d+/i.test(u.search)) return false;
    return true;
  } catch { return false; }
}

function cleanSearchUrl(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  try {
    const u = new URL(raw.startsWith("//") ? "https:" + raw : raw);
    if (u.protocol !== "https:" && u.protocol !== "http:") return "";
    return u.href;
  } catch { return ""; }
}

function isCampusHost(value, targetDomain = "xawl.edu.cn") {
  try {
    const host = new URL(String(value || "")).hostname.toLowerCase();
    const d = String(targetDomain || "").trim().toLowerCase();
    if (!d) return host.endsWith(".edu.cn");
    return host === d || host.endsWith("." + d);
  } catch { return false; }
}

const CAMPUS_INTENT_RE = /西安文理|文理学院|学校|校内|我校|教务处|学工|学院|辅导员|班主任|选课|补考|重修|缓考|期末考试|期末|学籍|转专业|专业分流|休学|复学|退学|毕业|学位|论文|查重|AIGC|学分|成绩|绩点|奖学金|助学金|助学贷款|困难认定|勤工助学|公寓|宿舍|留宿|校园卡|一卡通|医保|心理|评优|处分|档案|证明|盖章|申请表|手续|流程|规定|办法|制度|推免|保研|入党|党员|团委|学生会|社团|校医院|后勤|食堂|快递|校园网|学费|住宿费|缴费|户口|体检|军训|报到|注册|绿色通道|困难补助|勤工|评教|教务系统/;

function isCampusQuestion(text) {
  return CAMPUS_INTENT_RE.test(String(text || ""));
}

const TIME_SENSITIVE_RE = /最新|今年|去年|明年|近期|最近|这几天|本周|本月|截止|报名时间|什么时候|几号|放假|开学|通知|公告|现行|现行有效|调整|新规/;

function isTimeSensitiveQuestion(text) {
  return TIME_SENSITIVE_RE.test(String(text || ""));
}

function parseSourceDate(value) {
  const raw = String(value || "").trim();
  if (!raw) return 0;
  const m = raw.match(/(20\d{2})[-年/.](\d{1,2})[-月/.](\d{1,2})/);
  if (m) return Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  const y = raw.match(/(20\d{2})/);
  return y ? Date.UTC(Number(y[1]), 0, 1) : 0;
}

/* ---- 网页来源质量与官网优先级 ---- */

const SEARCH_ENGINE_HOSTS = new Set([
  "baidu.com", "m.baidu.com", "zhidao.baidu.com", "wenku.baidu.com",
  "so.com", "sogou.com", "bing.com", "google.com", "sm.cn"
]);
const NON_SOURCE_HOST_RE = /(^|\.)(docin|doc88|book118|renrendoc|zxxk|docer|mbalib|taobao|jd|1688)\.(com|cn)$/i;

function isNonSourceUrl(value) {
  try {
    const u = new URL(String(value || ""));
    const host = u.hostname.toLowerCase().replace(/^www\./, "");
    if (SEARCH_ENGINE_HOSTS.has(host)) return true;
    if (NON_SOURCE_HOST_RE.test(host)) return true;
    if (/^\/(s|search|so)(\/|$)/i.test(u.pathname)) return true;
    return false;
  } catch { return true; }
}

const TRACKING_KEY_RE = /^(utm_|spm$|from$|share|ref$|src$|_t$|timestamp$|sessionid$|sid$|chksm|scene$)/i;

function normalizeUrlKey(value) {
  try {
    const u = new URL(String(value || ""));
    if (u.protocol !== "http:" && u.protocol !== "https:") return "";
    const params = [...u.searchParams.entries()]
      .filter(([k]) => !TRACKING_KEY_RE.test(k))
      .sort((a, b) => a[0].localeCompare(b[0]));
    const qs = params.length ? "?" + params.map(([k, v]) => k + "=" + v).join("&") : "";
    return (u.hostname.toLowerCase().replace(/^www\./, "") + u.pathname.replace(/\/+$/, "") + qs).toLowerCase();
  } catch { return ""; }
}

function uniqList(list) {
  const seen = new Set();
  return (Array.isArray(list) ? list : []).filter(v => {
    const k = String(v || "").trim().toLowerCase();
    if (!k || seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

const WEB_NOISE_TERMS = new Set([
  "官网", "通知", "公告", "新闻", "动态", "大学", "西安", "文理", "学院", "我们",
  "问题", "相关", "内容", "信息", "情况", "工作", "学生", "学校", "规定", "办法",
  "管理", "办理", "流程", "申请", "材料", "文件", "页面", "网页", "网站", "地址"
]);

const QUESTION_FUNC_RE = /[的了是我你们请问怎么如何哪什么多少可以能有没想该那个会都也还就与和或及在到去来吧呢啊呀吗嘛哦嗯把被让给对从向于其之啦哈]/;

function trimTopicFragment(frag) {
  let t = String(frag || "");
  for (let i = 0; i < 3; i++) {
    const before = t;
    t = t
      .replace(/(需要|满足|想要|能否|可以|怎么办|怎么样|一下|准备)$/, "")
      .replace(/[丢找弄搞买卖拿取领借吃住不没未]$/, "")
      .replace(/^[些这那]/, "");
    if (t === before) break;
  }
  return t;
}

const QUESTION_PHRASE_RE = /(什么时候|什么时间|多少个工作日|多长时间|多久才能|多久|何时|哪一天|哪天|几号|几点|是多少|有哪些|是怎样的|需要多久)/g;

function topicFragments(question) {
  const q = String(question || "").toLowerCase().replace(QUESTION_PHRASE_RE, " ");
  const out = [];
  for (const run of q.match(/[a-z0-9\u3400-\u9fff][a-z0-9\u3400-\u9fff._-]*/g) || []) {
    for (const frag of run.split(QUESTION_FUNC_RE)) {
      const t = trimTopicFragment(frag);
      if (t.length >= 2) out.push(t.slice(0, 12));
    }
  }
  return out;
}

const TOPIC_FILLER_CHARS = /[需要满足]/;

function webTopicTerms(question) {
  const q = String(question || "").toLowerCase();
  const terms = [];
  const seen = new Set();
  const push = t => {
    if (t.length < 2) return;
    if (QUESTION_FUNC_RE.test(t)) return;
    if (TOPIC_FILLER_CHARS.test(t)) return;
    if (STOP_TERMS.has(t) || WEB_NOISE_TERMS.has(t) || GENERIC_TITLE_TERMS.has(t)) return;
    if (seen.has(t)) return;
    seen.add(t);
    terms.push(t);
  };
  for (const run of q.match(/[\u3400-\u9fff]+/g) || []) {
    for (let i = 0; i + 2 <= run.length; i++) push(run.slice(i, i + 2));
  }
  for (const tok of q.match(/[a-z0-9][a-z0-9._-]{1,}/g) || []) push(tok);
  for (const [spoken, expansions] of QUERY_SYNONYMS) {
    if (!q.includes(spoken)) continue;
    for (const t of expansions) if (/^[\u3400-\u9fff]{2,6}$/.test(t)) push(t);
  }
  return terms.slice(0, 32);
}

function titleCoversQuestion(question, title) {
  const terms = webTopicTerms(question);
  if (!terms.length) return false;
  const t = String(title || "").toLowerCase();
  if (!t) return false;
  let hit = 0;
  for (const term of terms) if (t.includes(term)) hit++;
  return hit / terms.length;
}

function webRelevance(question, item) {
  if (!item) return 0;
  const title = String(item.title || "");
  const body = String(item.snippet || item.summary || item.content || "");
  if (!title && !body) return 0;
  const terms = webTopicTerms(question);
  if (!terms.length) return 0.5;
  const hay = (title + " " + body).toLowerCase();
  const titleHay = title.toLowerCase();
  let total = 0, hit = 0, hitTerms = 0;
  for (const t of terms) {
    total += t.length;
    if (hay.includes(t)) { hit += t.length; hitTerms++; }
  }
  let cov = total ? hit / total : 0;
  if (terms.some(t => t.length >= 3 && titleHay.includes(t))) cov += 0.08;
  if (hitTerms <= 1 && cov < 0.6) cov *= 0.6;
  return Math.max(0, Math.min(1, cov));
}

function isMeaningfulSource(question, item, ctx) {
  if (!item || !isSpecificSourceUrl(item.url) || isNonSourceUrl(item.url)) return false;
  const body = String(item.snippet || item.content || "");
  if (body.length < 24) return false;
  const campus = isCampusHost(item.url, ctx && ctx.schoolDomain);
  const need = campus ? 0.3 : ((ctx && ctx.campusQuestion) ? 0.5 : 0.36);
  return webRelevance(question, item) >= need;
}

function rankWebResults(question, list, ctx) {
  const campusQuestion = !!(ctx && ctx.campusQuestion);
  const timeSensitive = !!(ctx && ctx.timeSensitive);
  const now = Date.now();
  const seen = new Set();
  const out = [];
  for (const r of Array.isArray(list) ? list : []) {
    const key = normalizeUrlKey(r && r.url);
    if (!key || seen.has(key)) continue;
    if (!isSpecificSourceUrl(r.url) || isNonSourceUrl(r.url)) continue;
    seen.add(key);
    const campus = isCampusHost(r.url, ctx && ctx.schoolDomain);
    const rel = webRelevance(question, r);
    let score = Number(r.score) || 0;
    if (campus) score += 1.15;
    else if (campusQuestion) score -= 0.7;
    if (Number(r.authority) >= 0) score += (Number(r.authority) - 2) * 0.08;
    const sName = (ctx && ctx.schoolName) || "西安文理学院";
    const titleStr = String(r.title || "");
    if (titleStr.includes(sName) || (sName === "西安文理学院" && /西安文理学院|文理学院/.test(titleStr))) score += 0.3;
    try {
      const uObj = new URL(String(r.url || ""));
      const hostLow = uObj.hostname.toLowerCase();
      if (campus && /^(jwc|jw|xsc|xg|xgb|gs|grs|xxgk|zs|rsc|office)\./i.test(hostLow)) score += 0.35;
      if (/\.gov\.cn$/i.test(hostLow)) score += 0.25;
      if (/\.(pdf|docx?)($|\?)/i.test(uObj.pathname)) score += 0.22;
      if (!campus && /(zhihu\.com|baidu\.com|wenk|doc88|book118|xiaohongshu|csdn\.net|sohu\.com|163\.com)/i.test(hostLow)) score -= 0.65;
    } catch {}
    score += rel * 1.25;
    if (timeSensitive) {
      const ts = parseSourceDate(r.date);
      if (ts) {
        const age = now - ts;
        if (age > 3 * 365 * 86400000) score -= 0.6;
        else if (age > 366 * 86400000) score -= 0.25;
      }
    }
    if (String(r.content || "").length >= 500) score += 0.1;
    out.push({ ...r, relevance: rel, isOfficial: campus, adjScore: score });
  }
  return out.sort((a, b) => (b.adjScore - a.adjScore) || (b.relevance - a.relevance));
}

function pickSources(question, ranked, ctx, limit) {
  const kept = [];
  const titleKeys = new Set();
  for (const r of Array.isArray(ranked) ? ranked : []) {
    if (kept.length >= limit) break;
    if (!isMeaningfulSource(question, r, ctx)) continue;
    const tKey = String(r.title || "").replace(/[\s\-—_|｜:：,，。.、·]+/g, "").slice(0, 26);
    if (tKey && titleKeys.has(tKey)) continue;
    if (tKey) titleKeys.add(tKey);
    kept.push(r);
  }
  return kept;
}

function topicPhrase(question) {
  const base = topicFragments(question).slice(0, 6).join(" ").trim();
  const expanded = expandQuery(base || String(question || ""));
  return (expanded || base || String(question || "")).slice(0, 56).trim();
}

async function searchWebSources(question, env, ctx) {
  const campusQuestion = !!(ctx && ctx.campusQuestion);
  const mode = (ctx && ctx.mode) || "manual";
  const started = Date.now();
  const queries = [];
  let officialKept = [];
  let dropped = 0;

  const runQueries = async (list, timeout, count) => {
    const settled = await Promise.allSettled(list.map(q => searchInternetCached(q, env, question, { timeout, count })));
    return settled.flatMap(item => (item.status === "fulfilled" && Array.isArray(item.value) ? item.value : []));
  };

  const sName = (ctx && ctx.schoolName) || "西安文理学院";
  const sDomain = (ctx && ctx.schoolDomain) || "";
  const isOtherSchool = sName !== "西安文理学院";
  if (campusQuestion || isOtherSchool) {
    const topic = topicPhrase(question);
    const siteExpr = sDomain ? `site:${sDomain}` : "site:edu.cn";
    const campusQueries = isOtherSchool
      ? uniqList([
          `${topic} ${siteExpr}`,
          `${sName} ${topic} 规定 办法 通知 ${siteExpr}`,
          `${sName} 教务处 学生处 ${topic} ${siteExpr}`
        ]).slice(0, 3)
      : uniqList([
          `${topic} ${siteExpr}`,
          `${sName} ${topic} ${siteExpr}`
        ]).slice(0, 2);
    queries.push(...campusQueries);
    const raw = await runQueries(campusQueries, isOtherSchool ? 8500 : (mode === "auto" ? 8000 : 7000), isOtherSchool ? 10 : 8);
    const ranked = rankWebResults(question, raw, ctx);
    officialKept = pickSources(question, ranked, ctx, isOtherSchool ? 10 : 5).filter(r => r.isOfficial);
    dropped += Math.max(0, ranked.length - officialKept.length);
    const strongOfficial = officialKept.some(r => r.relevance >= 0.45);
    const enough = isOtherSchool ? (officialKept.length >= 4) : (officialKept.length >= 2 || (officialKept.length >= 1 && strongOfficial));
    if (enough || (!isOtherSchool && mode === "auto")) {
      return { sources: officialKept.slice(0, isOtherSchool ? 8 : 4), official: officialKept.length > 0, stage: "campus", queries, dropped, ms: Date.now() - started };
    }
  }

  if (Date.now() - started > 6000) {
    return {
      sources: officialKept.slice(0, 4),
      official: officialKept.length > 0,
      stage: officialKept.length ? "campus" : "timeout",
      queries, dropped, ms: Date.now() - started
    };
  }

  const generalQueries = uniqList([`${sName} ${topicPhrase(question)}`, topicPhrase(question)])
    .filter(q => !queries.some(prev => prev.toLowerCase() === q.toLowerCase()))
    .slice(0, 2);
  queries.push(...generalQueries);
  const raw2 = await runQueries(generalQueries, 7000, 10);
  const ranked2 = rankWebResults(question, raw2, ctx);
  const generalKept = pickSources(question, ranked2, ctx, isOtherSchool ? 8 : 4);
  dropped += Math.max(0, ranked2.length - generalKept.length);

  const merged = [];
  const seen = new Set();
  for (const r of [...officialKept, ...generalKept]) {
    const key = normalizeUrlKey(r.url);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    merged.push(r);
    if (merged.length >= (isOtherSchool ? 8 : 4)) break;
  }
  return {
    sources: merged,
    official: officialKept.length > 0,
    stage: merged.length ? (officialKept.length ? "mixed" : "general") : "none",
    queries, dropped, ms: Date.now() - started
  };
}

function splitSentences(text) {
  const out = [];
  let buf = "";
  for (const ch of String(text || "")) {
    buf += ch;
    if ("。！？；!?;\n".includes(ch)) {
      if (buf.trim()) out.push(buf);
      buf = "";
    }
  }
  if (buf.trim()) out.push(buf);
  return out;
}

function excerptForQuestion(text, question, maxLen) {
  const clean = String(text || "").replace(/\s+/g, " ").trim();
  if (clean.length <= maxLen) return clean;
  const terms = knowledgeTerms(question).filter(t => t.length >= 2).slice(0, 24);
  const sentences = splitSentences(clean);
  if (!terms.length || sentences.length < 3) return clean.slice(0, maxLen);
  const rows = sentences.map((s, i) => {
    let hit = 0;
    for (const t of terms) if (s.includes(t)) hit++;
    return { i, s, hit };
  });
  const keep = new Set();
  let used = 0;
  for (const row of [...rows].sort((a, b) => b.hit - a.hit)) {
    if (row.hit <= 0 || used >= maxLen) break;
    keep.add(row.i);
    used += row.s.length;
  }
  if (!keep.size) return clean.slice(0, maxLen);
  let out = "";
  let last = -2;
  for (const row of rows) {
    if (!keep.has(row.i)) continue;
    out += row.i === last + 1 ? row.s : (out ? " … " : "") + row.s;
    last = row.i;
  }
  return out.slice(0, maxLen + 200);
}

const FOLLOW_UP_START_RE = /^(那|这|它|其|还有|那么|然后|如果|需要|可以|具体|大概|多久|几份|哪里|怎么|什么时候|要不要)/;

function withLastQuestion(question, history) {
  const q = String(question || "").trim();
  if (!q || q.length > 20 || !Array.isArray(history) || !history.length) return q;
  if (!FOLLOW_UP_START_RE.test(q)) return q;
  const prev = [...history].reverse().find(m => m && m.role === "user" && m.content);
  if (!prev) return q;
  const stem = (kbTopicWords(prev.content).slice(0, 2).join(" ")
    || String(prev.content).replace(/\s+/g, " ").trim().slice(0, 24)).slice(0, 40);
  if (!stem || stem.includes(q)) return q;
  return (stem + " " + q).slice(0, 180);
}

const SEARCH_MEM_CACHE = new Map();
const FETCH_MEM_CACHE = new Map();

function memGet(map, key) {
  const hit = map.get(key);
  if (!hit) return null;
  if (hit.exp < Date.now()) { map.delete(key); return null; }
  return hit.value;
}

function memSet(map, key, value, ttlMs) {
  if (map.size > 200) map.clear();
  map.set(key, { value, exp: Date.now() + ttlMs });
}

async function searchInternetCached(query, env, originalQuestion, opts) {
  const key = "https://deepseek-search-cache.internal/" + hashText(String(query || "").toLowerCase().trim());
  const local = memGet(SEARCH_MEM_CACHE, key);
  if (local) return local;
  const hit = await readAnswerCache(key);
  if (hit && Array.isArray(hit.results)) {
    memSet(SEARCH_MEM_CACHE, key, hit.results, 21600000);
    return hit.results;
  }
  const results = await searchInternet(query, env, originalQuestion, opts);
  if (results && results.length) {
    await writeAnswerCache(key, { results }, 21600);
    memSet(SEARCH_MEM_CACHE, key, results, 21600000);
  } else {
    await writeAnswerCache(key, { results: [] }, 1800);
    memSet(SEARCH_MEM_CACHE, key, [], 1800000);
  }
  return results || [];
}

async function fetchPageCached(url, env) {
  const key = "https://deepseek-fetch-cache.internal/" + hashText(String(url || "").toLowerCase().trim());
  const local = memGet(FETCH_MEM_CACHE, key);
  if (local) return local;
  const hit = await readAnswerCache(key);
  if (hit && hit.content) {
    memSet(FETCH_MEM_CACHE, key, hit, 86400000);
    return hit;
  }
  const page = await fetchInternetPage(url, env);
  if (page && page.content) {
    await writeAnswerCache(key, page, 86400);
    memSet(FETCH_MEM_CACHE, key, page, 86400000);
  }
  return page;
}

async function searchInternet(query, env, originalQuestion, opts) {
  const q = String(query || "").trim().slice(0, 128);
  if (!q) return [];
  const options = opts || {};
  const apiKey = env.DEEPSEEK_API_KEY || env.AI_API_KEY;
  if (!apiKey) throw new Error("未配置 DEEPSEEK_API_KEY，无法调用 DeepSeek 官方联网搜索接口");

  const response = await fetchJsonWithTimeout("https://api.deepseek.com/v1/tools/search", {
    method: "POST",
    headers: {
      "Authorization": "Bearer " + apiKey,
      "Content-Type": "application/json",
      "Accept": "application/json"
    },
    body: JSON.stringify({
      query: q,
      count: Math.min(Math.max(Number(options.count) || 10, 4), 20),
      ori_question: String(originalQuestion || query || "").trim().slice(0, 128) || undefined,
      need_content: true
    }),
    signal: AbortSignal.timeout(Number(options.timeout) || 15000)
  });

  if (!response.ok) {
    let detail = "";
    try {
      const errorData = await response.json();
      detail = String(errorData && errorData.error && errorData.error.message || "").slice(0, 180);
    } catch {}
    throw new Error("DeepSeek 官方搜索接口返回 HTTP " + response.status + (detail ? "：" + detail : ""));
  }

  const data = await response.json();
  if (!Array.isArray(data.results)) throw new Error("DeepSeek 搜索接口返回格式异常");
  return data.results.map(r => {
    const url = cleanSearchUrl(r && r.url);
    const content = String(r && r.content || "").trim();
    const summary = String(r && r.summary || "").trim();
    const snippet = String(r && r.snippet || "").trim();
    return {
      title: String(r && r.title || url || "网页来源").slice(0, 200),
      url,
      content: content.slice(0, 9000),
      summary: summary.slice(0, 1800),
      snippet: (content || summary || snippet).slice(0, 6000),
      date: r && r.date || null,
      score: Number.isFinite(Number(r && r.rerank_score)) ? Number(r.rerank_score) : 0,
      authority: Number.isFinite(Number(r && r.authority)) ? Number(r.authority) : -1,
      siteName: String(r && r.site_name || "").slice(0, 120)
    };
  }).filter(r => isSpecificSourceUrl(r.url) && (r.snippet || r.summary || r.content))
    .sort((a, b) => (b.score - a.score) || (b.authority - a.authority));
}

function expandQuery(text) {
  let out = String(text || "");
  for (const [spoken, expansions] of QUERY_SYNONYMS) {
    if (!out.includes(spoken)) continue;
    const official = expansions.find(t => t !== spoken);
    if (official && !out.includes(official)) out += " " + official;
  }
  return out.replace(/\s+/g, " ").trim();
}

async function fetchInternetPage(url, env) {
  const apiKey = env.DEEPSEEK_API_KEY || env.AI_API_KEY;
  if (!apiKey || !cleanSearchUrl(url)) return null;
  try {
    const response = await fetchJsonWithTimeout("https://api.deepseek.com/v1/tools/fetch", {
      method: "POST",
      headers: {
        "Authorization": "Bearer " + apiKey,
        "Content-Type": "application/json",
        "Accept": "application/json"
      },
      body: JSON.stringify({ url: cleanSearchUrl(url) }),
      signal: AbortSignal.timeout(9000)
    }, 10000);
    if (!response.ok) return null;
    const page = await response.json();
    const content = String(page && page.content || "").trim();
    if (!content) return null;
    return {
      title: String(page.title || "").slice(0, 200),
      content: content.slice(0, 6500)
    };
  } catch {
    return null;
  }
}

function getOfficialDocumentUrl(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  try {
    const u = new URL(raw);
    if (u.protocol !== "https:" && u.protocol !== "http:") return "";
    const host = u.hostname.toLowerCase();
    if (!(host === "xawl.edu.cn" || host.endsWith(".xawl.edu.cn"))) return "";
    const path = u.pathname.replace(/\/+$/, "").toLowerCase();
    const genericPaths = new Set([
      "", "/index.htm", "/index.html", "/index.jsp", "/index.php",
      "/tzgg.htm", "/tzgg.html", "/通知公告", "/"
    ]);
    if (genericPaths.has(path)) return "";
    return u.href;
  } catch {
    return "";
  }
}

function buildDocCatalog(chunks) {
  const map = new Map();
  let idx = 1;
  for (const c of chunks) {
    const title = c.docTitle || c.name;
    if (!map.has(title)) {
      let preview = String(c.content || "").replace(/^\s*【\d{3}】\s*/, "");
      if (preview.startsWith(title)) preview = preview.slice(title.length);
      preview = preview.replace(/^\s*【(?:部门|栏目|日期|链接)】[^\n]*(?:\n|$)/gm, "");
      preview = preview.replace(/^（[^）]{0,80}）\s*/, "");
      preview = preview.replace(/\s+/g, " ").trim().slice(0, 160);
      map.set(title, {
        id: idx,
        catalog_no: c.docNo || String(idx).padStart(3, "0"),
        title,
        dept: c.dept || "学校部门",
        category: c.category || "规章制度",
        date: c.date || "",
        url: getOfficialDocumentUrl(c.url),
        chunk_count: 0,
        preview
      }, 8000);
      idx++;
    }
    map.get(title).chunk_count++;
  }
  return [...map.values()];
}

const KNOWLEDGE_DOCS = buildDocCatalog(KNOWLEDGE_CHUNKS);
const KNOWLEDGE_DOC_COUNT = KNOWLEDGE_DOCS.length;

const RATE_LIMIT_MAP = new Map();
const RATE_LIMIT_MAX = 30;
const RATE_LIMIT_WINDOW_MS = 60000;

const AUTH_LIMIT_MAP = new Map();
const AUTH_LIMIT_MAX = 20;
const AUTH_LIMIT_WINDOW_MS = 60000;

function checkRateLimit(map, ip, maxCount, windowMs, errorMsg) {
  const nowMs = Date.now();
  let rl = map.get(ip);
  if (!rl || rl.resetAt < nowMs) {
    rl = { count: 0, resetAt: nowMs + windowMs };
    map.set(ip, rl);
  }
  rl.count++;
  if (rl.count > maxCount) {
    throw err(errorMsg, 429);
  }
  if (map.size > 5000) map.clear();
}

/* ---- AI 增强：缓存 / 追问 / 降级 ---- */

function hashText(value) {
  let h = 2166136261;
  const s = String(value || "");
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(36);
}

const SSE_HEADERS = {
  "Content-Type": "text/event-stream; charset=utf-8",
  "Cache-Control": "no-cache, no-transform",
  "Connection": "keep-alive",
  "X-Accel-Buffering": "no"
};

function sseFrame(obj) {
  return `data: ${JSON.stringify(obj)}\n\n`;
}

function sseResponse(frames, headers) {
  const encoder = new TextEncoder();
  return new Response(encoder.encode(frames.join("")), {
    status: 200,
    headers: { ...headers, ...SSE_HEADERS }
  });
}

function sseStreamText(metaObj, fullText, headers) {
  const { readable, writable } = new TransformStream();
  const writer = writable.getWriter();
  const encoder = new TextEncoder();
  (async () => {
    try {
      await writer.write(encoder.encode(sseFrame(metaObj)));
      const str = String(fullText || "");
      const chunkLen = Math.max(12, Math.min(28, Math.ceil(str.length / 26)));
      for (let i = 0; i < str.length; i += chunkLen) {
        const piece = str.slice(i, i + chunkLen);
        await writer.write(encoder.encode(sseFrame({ choices: [{ delta: { content: piece } }] })));
        await new Promise(r => setTimeout(r, 18));
      }
      await writer.write(encoder.encode("data: [DONE]\n\n"));
    } catch {} finally {
      try { await writer.close(); } catch {}
    }
  })();
  return new Response(readable, {
    status: 200,
    headers: { ...headers, ...SSE_HEADERS }
  });
}

async function readAnswerCache(key) {
  try {
    if (typeof caches === "undefined" || !caches.default) return null;
    const hit = await caches.default.match(key);
    if (!hit) return null;
    return await hit.json();
  } catch {
    return null;
  }
}

async function writeAnswerCache(key, value, ttlSeconds) {
  try {
    if (typeof caches === "undefined" || !caches.default) return;
    await caches.default.put(key, new Response(JSON.stringify(value), {
      headers: {
        "Content-Type": "application/json; charset=utf-8",
        "Cache-Control": "max-age=" + ttlSeconds
      }
    }));
  } catch {
  }
}

function collectStreamText(raw) {
  let answer = "";
  let reasoning = "";
  let error = "";
  for (const line of String(raw || "").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("data:")) continue;
    const payload = trimmed.slice(5).trim();
    if (!payload || payload === "[DONE]") continue;
    try {
      const obj = JSON.parse(payload);
      if (obj && obj.error) {
        error = String(obj.error).slice(0, 200);
        continue;
      }
      const delta = obj && obj.choices && obj.choices[0] && obj.choices[0].delta;
      if (!delta) continue;
      if (delta.reasoning_content) reasoning += delta.reasoning_content;
      if (delta.content) answer += delta.content;
    } catch {
    }
  }
  return { answer, reasoning, error };
}

const ANSWER_TAIL_OK = /[。！？…」』”"'）)\]】》!?.~～]$/;
const ANSWER_TAIL_BAD = /[，、,;；:：·（(\[【《〈“"'\-—]$/;
const ANSWER_TAIL_CUT = /[的该和与或及以于并且是在对为把被从此等而但就都也还很更最不没无]$/;

function looksDone(text) {
  const t = String(text || "").trimEnd();
  if (!t) return false;
  const openers = (t.match(/[（(\[【《〈“‘]/g) || []).length;
  const closers = (t.match(/[）)\]】》〉”’]/g) || []).length;
  if (openers > closers) return false;
  if (ANSWER_TAIL_BAD.test(t)) return false;
  if (ANSWER_TAIL_CUT.test(t)) return false;
  if (ANSWER_TAIL_OK.test(t)) return true;
  const lastLine = t.split("\n").map(s => s.trim()).filter(Boolean).pop() || "";
  if (/^(?:\d{1,2}[.、)）]|[①-⑳]|[-*•▪])/.test(lastLine)
    && lastLine.replace(/^(?:\d{1,2}[.、)）]|[①-⑳]|[-*•▪])\s*/, "").length >= 10) return true;
  return t.length <= 20;
}

const FOLLOWUP_TOPICS = [
  { re: /心理|咨询|情绪|焦虑|抑郁|危机/, items: ["咨询是免费的吗？", "可以匿名预约吗？", "一次咨询多长时间？"] },
  { re: /公寓|宿舍|留宿|住宿|门禁/, items: ["需要学院盖章吗？", "假期中途能续住吗？", "水电和门禁怎么安排？"] },
  { re: /论文|查重|AIGC|答辩|开题|选题|盲审/, items: ["查重不通过怎么办？", "需要导师签字吗？", "答辩一般在几月？"] },
  { re: /奖学金|助学金|困难|资助|贷款|勤工助学/, items: ["评审什么时候开始？", "结果要公示吗？", "金额和名额怎么定？"] },
  { re: /缓考|补考|重修|作弊|违纪|考试成绩|取消考试资格/, items: ["需要提前多久申请？", "成绩怎么记载？", "影响评优或毕业吗？"] },
  { re: /转专业|专业分流/, items: ["什么时候可以申请？", "名额和成绩要求？", "已修学分怎么认定？"] },
  { re: /学位|绩点|毕业证|毕业资格/, items: ["绩点怎么计算？", "不达标还有补救吗？", "什么时候发证？"] },
  { re: /休学|复学|退学|保留学籍|学籍/, items: ["需要哪些材料？", "学籍能保留多久？", "影响毕业时间吗？"] },
  { re: /学分置换|学分认定|置换/, items: ["哪些项目能置换？", "最多能置换多少？", "由谁审核认定？"] }
];

async function judgeEvidence(question, items, opts) {
  const list = Array.isArray(items) ? items.slice(0, 4) : [];
  if (list.length < 2) return null;
  const { apiKey, base, model, timeoutMs = 2600 } = opts || {};
  if (!apiKey || !base) return null;

  const body = list.map((it, i) => {
    const raw = String(it.content || it.snippet || "");
    const excerpt = excerptForQuestion(raw, question, 420) || raw;
    return `【A${i + 1}】《${it.docTitle || it.name || "未命名文件"}》\n${excerpt.slice(0, 420)}`;
  }).join("\n\n");

  const prompt = `判断下面每段校内材料能否直接回答学生的问题。你只做判断，不回答问题。

问题：${question}

${body}

判断标准：
- 答“是”：正文里能读到回答所需的实体信息——具体条款、数字或额度、时限、适用条件、办理部门、步骤、材料名称；
- 答“否”：只是同一话题的泛泛表述、需要大量推测才能用、或换成别的问题也照样这么写。
按下面的格式输出，每段一行，不要解释、不要空行、不要编号以外的文字：
A1=是
A2=否`;

  try {
    const res = await fetch(base + "/chat/completions", {
      method: "POST",
      headers: { "Authorization": "Bearer " + apiKey, "Content-Type": "application/json" },
      body: JSON.stringify({
        model,
        stream: false,
        temperature: 0,
        max_tokens: 60,
        thinking: { type: "disabled" },
        messages: [{ role: "user", content: prompt }]
      }),
      signal: AbortSignal.timeout(timeoutMs)
    });
    if (!res.ok) return null;
    const data = await res.json();
    const text = String(data?.choices?.[0]?.message?.content || "");

    const keep = new Set();
    let denied = 0;
    for (const m of text.matchAll(/A(\d)\s*[=＝:：]\s*(是|否|能|不能|有|无|yes|no)/gi)) {
      const idx = Number(m[1]) - 1;
      if (idx < 0 || idx >= list.length) continue;
      if (/^(是|能|有|yes)$/i.test(m[2])) keep.add(idx);
      else denied++;
    }
    if (!keep.size && !denied) return null;
    if (!keep.size) keep.add(0);
    return keep;
  } catch {
    return null;
  }
}

const META_SENTENCE_RES = [
  /(链接|网址|URL|来源)[^。！？\n]{0,24}(伪造|编造|虚构|捏造|造假|真伪|真实性|虚假|不实)/i,
  /(伪造|编造|虚构|捏造)[^。！？\n]{0,12}(链接|网址|URL|来源)/i,
  /(以上|以下|下方|下列|下面|这些|本文|本次)[^。！？\n]{0,10}(链接|网址|来源)[^。！？\n]{0,20}(均|都|已|可|真实|有效|官方|来自|核对|验证)/,
  /(链接|网址|来源)[^。！？\n]{0,12}(均|都)(为|是|来自|可|已)[^。！？\n]{0,12}(官网|官方|原文|真实|有效|核对)/,
  /(链接|网址)[^。！？\n]{0,12}(放心|安全|保真|不会失效|均可打开)/,
  /(未|没有|不)(会)?(自行)?(拼接|生成|编造|伪造)[^。！？\n]{0,8}(链接|网址|URL)/i,
  /(检索|搜索|查找|匹配)[^。！？\n]{0,12}(过程|日志|记录)[^。！？\n]{0,10}(不|无|省略|此处|如下)/,
];

function stripMetaTalk(text) {
  let out = String(text || "");
  if (!out) return out;

  out = out.replace(/[（(]\s*(注|说明|备注|提示)\s*[:：][^）)]{0,160}[）)]/g, m =>
    /链接|网址|来源|检索|搜索|伪造|编造|真实|有效|URL/i.test(m) ? "" : m
  );

  out = (out.match(/[^。！？；\n]+[。！？；\n]*/g) || [])
    .filter(seg => !META_SENTENCE_RES.some(re => re.test(seg)))
    .join("");

  out = out
    .replace(/[ \t]+([，。；：、！？])/g, "$1")
    .replace(/[（(]\s*[)）]/g, "")
    .replace(/^[ \t]*[-*·][ \t]*$/gm, "")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]+$/gm, "")
    .trim();
  return out;
}

function detectAnswerConfidence(matched, webSources, topRel, weakMatch) {
  const list = Array.isArray(webSources) ? webSources : [];
  if (list.some(r => r.isOfficial && Number(r.relevance) >= 0.5)) return "high";
  if (weakMatch) return list.length ? "medium" : "low";
  if (!matched || !matched.length) return list.length ? "medium" : "low";
  if (topRel >= 0.62) return "high";
  if (topRel >= 0.46) return "medium";
  return "low";
}

const CONFIDENCE_PROMPT = {
  high: "【本次依据强度：强】已找到与问题直接对应的校内文件或官网页面。可以直接给出条款、数量、时限与办理地点，但必须写明依据的文件名；细节以原文为限。",
  medium: "【本次依据强度：中】只找到部分相关材料。可以给出原则与主流程；凡涉及具体数字、时限、地点、材料份数，注明“以主管部门最新通知为准”。",
  low: "【本次依据强度：弱】没有检索到可直接依据的原文。只回答“该找谁、大致怎么走、要准备哪类材料”，禁止给出条款号、金额、时限、文号；开头用一句话说明依据有限即可。"
};

function detectQuestionKind(question) {
  const q = String(question || "");
  if (/什么时候|几月|几号|截止|多久|期限|时间安排|哪天|到期/.test(q)) {
    return { key: "timing", prompt: "【本次问题类型：时间节点】先回答时间，再说明由谁发布、以哪份通知为准；日期只写原文给出的，原文没写的就写去哪查。" };
  }
  if (/能不能|可不可以|会不会|是否|算不算|有没有|允许|行不行|(能|可以|允许|准|让).{0,10}(吗|么|嘛)/.test(q)) {
    return { key: "judge", prompt: "【本次问题类型：能否/是否】先给“能 / 不能 / 视情况”的明确判断，再给依据与例外情形。" };
  }
  if (/多少|标准|要求|条件|资格|比例|上限|绩点|分数|周数|字数|金额|几年|几份/.test(q)) {
    return { key: "standard", prompt: "【本次问题类型：标准/条件】先给准确数值或条件，再补适用范围与例外；数值必须来自原文，没有就明说没有。" };
  }
  if (/怎么办|怎么|如何|流程|办理|申请|手续|步骤|找谁|到哪/.test(q)) {
    return { key: "procedure", prompt: "【本次问题类型：办事流程】按“结论 → 材料 → 分步流程 → 卡点提醒”组织，步骤要写清动作对象与办理地点。" };
  }
  if (/是什么|什么意思|包括|定义|区别/.test(q)) {
    return { key: "concept", prompt: "【本次问题类型：概念解释】用 3-5 句话讲清含义与适用场景，必要时举一个校内例子。" };
  }
  return { key: "general", prompt: "【本次问题类型：一般咨询】先直接回答，再补充最关键的 1-2 个注意事项。" };
}

function buildFollowUps(question, matched) {
  const q = String(question || "");
  const out = [];
  const push = text => {
    const t = String(text || "").trim();
    if (t && !out.includes(t)) out.push(t);
  };
  const topic = FOLLOWUP_TOPICS.find(t => t.re.test(q));
  if (topic) topic.items.forEach(push);
  if (out.length < 3) {
    if (/流程|怎么办|如何|办理|手续|步骤|申请|预约/.test(q)) {
      push("需要准备哪些材料？");
      push("去哪个部门办理？");
      push("大概多久能办完？");
    } else if (/条件|资格|要求|能不能|多少|比例|时间|截止/.test(q)) {
      push("不达标会有什么后果？");
      push("还有什么补救办法？");
      push("具体找谁核实？");
    } else {
      push("需要准备哪些材料？");
      push("具体找哪个部门？");
    }
  }
  return out.slice(0, 3);
}

function buildOfflineAnswer(question, matched) {
  const head = "⚠️ 智能生成服务暂时繁忙，先直接给你校内制度原文作为依据：\n\n";
  if (!matched || !matched.length) {
    if (isScheduleQuestion(question)) {
      return "⚠️ 智能生成服务暂时繁忙，请稍等几秒再试，或直接前往左侧「超级课表」查看今日课程。";
    }
    return head +
      "校内文件库中没有检索到与这个问题直接相关的规定。\n\n" +
      "建议按下面顺序处理：\n" +
      "1. 到「校规制度库」用关键词再搜一次（如：缓考、转专业、学分置换）；\n" +
      "2. 先问辅导员或二级学院教务科/学工办；\n" +
      "3. 涉及学籍、考试、毕业、资助的，直接联系教务处或学生工作部。";
  }
  const parts = matched.slice(0, 3).map((doc, i) => {
    const title = String(doc.docTitle || doc.name || "校内文件").replace(/^【\d+】\s*/, "").trim();
    const body = String(doc.content || "").replace(/\s+/g, " ").slice(0, 240);
    return `**${i + 1}. 《${title}》**\n> ${body}…`;
  });
  return head + parts.join("\n\n") +
    "\n\n以上为制度原文摘录，完整条款可在「校规制度库」查看。具体办理请以教务处、学生工作部最新通知为准。";
}


